function reviewPublicTargetTools(){
 return S.user?.reviewService
  ? btn('浏览服务公开目标','review-visible-targets','ghost')+reviewPublicSearchTools()+
    btn('浏览公开实践','review-public-practices','ghost')+
    '<a class="ghost" href="/platform/product.html?view=discover">浏览知识需求</a>'
  : '';
}
function reviewAddTargetDemandLink(target){
 const link=document.createElement('a');
 link.className='ghost';
 link.href='/platform/product.html?'+new URLSearchParams({view:'discover',treeId:target.treeId,nodeId:target.nodeId});
 link.textContent='浏览这个目标的需求';
 document.getElementById('visible-target-start').after(link);
}
async function reviewOpenVisibleTargets(query=''){const context=reviewContext();modal(`<h2>发现公开目标</h2><p class="small muted">读取其他使用者主动展示的目标定义，不读取私人教程、笔记或实践。个人公开目标仍由其持有人拥有。</p><form id="visible-target-search" class="row" style="margin:16px 0"><input name="query" type="search" aria-label="搜索服务公开目标" maxlength="120" value="${esc(query)}" placeholder="名称、领域或目标内容"><button>搜索</button></form><p id="visible-target-status" class="small muted" role="status"></p><div id="visible-target-results"></div>`,'','服务公开目标');const form=document.getElementById('visible-target-search'),results=document.getElementById('visible-target-results'),status=document.getElementById('visible-target-status');let busy=false;
 async function load(cursor=''){if(busy||!form.isConnected||!reviewContextCurrent(context))return;busy=true;form.querySelector('button').disabled=true;status.textContent='正在读取服务公开目标…';const q=form.elements.namedItem('query').value;
  try{const r=await reviewKnowledgeRequest('/api/review-visible-targets?query='+encodeURIComponent(q)+(cursor?'&cursor='+encodeURIComponent(cursor):''),{context});if(!form.isConnected)return;if(!Array.isArray(r.targets)||r.ownerId!==context.ownerId)throw Error('公开目录回执不一致，请重新读取。');status.textContent=`找到 ${r.total} 个当前公开目标。本页 ${r.targets.length} 个。`;results.innerHTML=r.targets.map((n,i)=>`<article class="list-row"><h3>${esc(n.title)}</h3><p class="small muted">${esc(n.domain)} / ${esc(n.branch)} · ${esc(n.ownerName)} · 目标 v${n.sourceVersion}</p><p class="pre small">${esc(n.goal)}</p><button class="ghost" data-visible-index="${i}">查看完整目标与起步</button></article>`).join('')||'<p class="small muted">没有符合搜索的公开目标。可以换个词再试。</p>';results.querySelectorAll('[data-visible-index]').forEach(b=>b.addEventListener('click',()=>{if(b.isConnected)reviewShowVisibleTarget(r.targets[Number(b.dataset.visibleIndex)],context,q)}));if(r.nextCursor){const next=document.createElement('button');next.textContent='下一页公开目标';next.addEventListener('click',()=>load(r.nextCursor));results.append(next)}}catch(error){if(form.isConnected&&reviewContextCurrent(context)){status.textContent=error.message;const retry=document.createElement('button');retry.textContent='重新读取第一页';retry.addEventListener('click',()=>load());results.append(retry)}}finally{busy=false;form.querySelector('button').disabled=false}}
 form.addEventListener('submit',ev=>{ev.preventDefault();load()});await load();}
function reviewShowVisibleTarget(target,context,query,pathReference=null){if(!reviewContextCurrent(context))return;modal(`<h2>${esc(target.title)}</h2><p class="small muted">${esc(target.domain)} / ${esc(target.branch)} · 个人持有人：${esc(target.ownerName)} · 目标 v${target.sourceVersion}</p><h3 style="margin-top:18px">完整目标</h3><p class="pre">${esc(target.goal)}</p><h3 style="margin-top:18px">下一段五分钟</h3><p class="pre">${esc(target.five)}</p><p class="small muted">可以独立尝试，或选用下面的教程。开始前核对所选版本；结束计时不自动确认点亮。</p><p id="visible-target-start-error" class="error" role="alert"></p><div class="row actions"><button id="visible-target-start" class="primary">独立尝试 · 开始计时</button><button id="visible-target-back" class="ghost">返回公开目标</button></div>`,'','公开目标详情');reviewVisibleMethods(target,context,pathReference);reviewAddTargetDemandLink(target);const button=document.getElementById('visible-target-start');document.getElementById('visible-target-back').addEventListener('click',()=>reviewOpenVisibleTargets(query));button.addEventListener('click',async()=>{if(!button.isConnected||button.disabled)return;button.disabled=true;try{const r=await reviewKnowledgeRequest('/api/review-visible-targets/one?nodeId='+encodeURIComponent(target.nodeId),{context});if(!button.isConnected||!reviewContextCurrent(context))return;if(JSON.stringify(r.target)!==JSON.stringify(target))throw Error('目标已修订，请返回结果重新核对后开始。');closeModal();start(target.title,{knowledge:{...(pathReference?{pathReference:clone(pathReference)}:{}),nodeId:target.nodeId,nodeTitle:target.title,nodeGoal:target.goal,nodeVersion:target.sourceVersion,nodeDomain:target.domain,nodeBranch:target.branch,nodeOwnership:target.ownership,nodeVisibility:'public',methodId:null,methodTitle:'独立尝试',version:null,content:'',resource:'',five:target.five,targetServiceReference:{nodeId:target.nodeId,treeId:target.treeId,targetVersion:target.version,sourceVersion:target.sourceVersion,ownerId:target.ownerId}}});toast('公开目标的当时定义已进入这次独立实践。')}catch(error){if(button.isConnected&&reviewContextCurrent(context))document.getElementById('visible-target-start-error').textContent=error.message}finally{button.disabled=false}})}
